#!/usr/bin/env node
// Digest a captured conversation JSONL into a readable trace.
import { createInterface } from 'node:readline';

const rl = createInterface({ input: process.stdin });
let t0 = null;
const out = [];
for await (const line of rl) {
  if (!line.trim()) continue;
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const ts = e.timestamp ? new Date(e.timestamp) : null;
  if (ts && !t0) t0 = ts;
  const rel = ts && t0 ? Math.round((ts - t0) / 1000) : '';
  const m = e.message;
  if (!m) continue;
  if (e.type === 'user') {
    const c = m.content;
    if (typeof c === 'string') {
      if (c.startsWith('<system-reminder>') || c.startsWith('Caveat:')) continue;
      out.push(`[${rel}s] USER: ${c.slice(0, 2500)}`);
    } else if (Array.isArray(c)) {
      for (const b of c) {
        if (b.type === 'text') {
          if (b.text.startsWith('<system-reminder>')) continue;
          out.push(`[${rel}s] USER: ${b.text.slice(0, 2500)}`);
        } else if (b.type === 'tool_result') {
          const txt = typeof b.content === 'string' ? b.content
            : Array.isArray(b.content) ? b.content.map(x => x.text || `<${x.type}>`).join(' ') : '';
          const err = b.is_error ? 'ERR ' : '';
          out.push(`[${rel}s]   <- ${err}${(txt || '').replace(/\s+/g, ' ').slice(0, 300)}`);
        }
      }
    }
  } else if (e.type === 'assistant') {
    for (const b of m.content || []) {
      if (b.type === 'text' && b.text.trim()) {
        out.push(`[${rel}s] ASSISTANT: ${b.text.replace(/\n{2,}/g, '\n').slice(0, 2000)}`);
      } else if (b.type === 'tool_use') {
        const inp = JSON.stringify(b.input).replace(/\s+/g, ' ').slice(0, 400);
        out.push(`[${rel}s]   -> ${b.name} ${inp}`);
      }
    }
  }
}
console.log(out.join('\n'));

